def latest(events):
    result = {}
    for seq, op, key in sorted(events):
        result[key] = op
    return result

events = [(1, "I", 1), (2, "I", 2), (3, "U", 1), (4, "D", 2), (5, "I", 3)]
print(sorted(latest(events).items()))

