import sqlite3

conn = sqlite3.connect(":memory:")
conn.executescript("""
CREATE TABLE items (id INTEGER PRIMARY KEY, price INTEGER);
CREATE TABLE log (seq INTEGER PRIMARY KEY AUTOINCREMENT, op TEXT, id INTEGER, price INTEGER);
CREATE TRIGGER a_ins AFTER INSERT ON items BEGIN INSERT INTO log (op, id, price) VALUES ('I', NEW.id, NEW.price); END;
CREATE TRIGGER a_upd AFTER UPDATE ON items BEGIN INSERT INTO log (op, id, price) VALUES ('U', NEW.id, NEW.price); END;
CREATE TRIGGER a_del AFTER DELETE ON items BEGIN INSERT INTO log (op, id, price) VALUES ('D', OLD.id, NULL); END;
""")
conn.execute("INSERT INTO items VALUES (1, 10)")
conn.execute("UPDATE items SET price = 12 WHERE id = 1")
conn.execute("INSERT INTO items VALUES (2, 7)")
conn.execute("DELETE FROM items WHERE id = 1")
for row in conn.execute("SELECT * FROM log ORDER BY seq"):
    print(row)
